import subprocess
import sys
from pathlib import Path

import pytest

HERE = Path(__file__).resolve().parent


def run_gen(*extra):
    return subprocess.run([sys.executable, str(HERE / "gen_log.py"), *extra],
                          capture_output=True, text=True)


def run_verify():
    return subprocess.run([sys.executable, str(HERE / "verify_log.py")],
                          capture_output=True, text=True)

